CREATE TABLE patient_basic_info (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL, study_no VARCHAR(100), gender INT, age INT, card_no VARCHAR(30), mobile VARCHAR(30), nation VARCHAR(30), marry INT, create_date DATETIME, createDate DATETIME, confirm_date DATE, confirmDate DATE, happen_date DATE, happenDate DATE, follow_cycle INT DEFAULT 3, height VARCHAR(30), weight VARCHAR(30), waistline VARCHAR(30), xl VARCHAR(30), xy VARCHAR(30), xy_h VARCHAR(30), xy_l VARCHAR(30), acr_eular_score INT, acrEularScore INT, drink INT, drink_count_by_day VARCHAR(30), drinkCountByDay VARCHAR(30), drink_years VARCHAR(30), drinkYears VARCHAR(30), smoke INT, smoke_years VARCHAR(30), smokeYears VARCHAR(30), smoke_count_by_day VARCHAR(30), smokeCountByDay VARCHAR(30), smoke_stop INT, smokeStop INT, allergy VARCHAR(1000), gms VARCHAR(1000), jzs VARCHAR(1000), jws VARCHAR(2000)) ENGINE=InnoDB;
CREATE TABLE patient_relation_doctor (id BIGINT PRIMARY KEY AUTO_INCREMENT, doctor_id BIGINT NOT NULL, patient_id BIGINT NOT NULL, research_type INT DEFAULT 0, miss INT DEFAULT 0, reason VARCHAR(200), other_miss_reason VARCHAR(200), note VARCHAR(200)) ENGINE=InnoDB;
CREATE TABLE patient_follow_up_history (id BIGINT PRIMARY KEY, patient_basic_info_id BIGINT NOT NULL, research_type INT DEFAULT 0, doctor_id BIGINT, follow_up_date DATETIME, followUpDate DATETIME, last_follow_up_id BIGINT, bsbq TEXT, bqpg TEXT, fzjc TEXT, zyzd TEXT, zlfa TEXT, blsj TEXT, bblsj TEXT) ENGINE=InnoDB;
CREATE TABLE patient_comorbidity (id BIGINT PRIMARY KEY, patient_id BIGINT, disease_code VARCHAR(30), since_year INT) ENGINE=InnoDB;
CREATE TABLE `user` (id BIGINT PRIMARY KEY, name VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE patient_audit_log (id BIGINT PRIMARY KEY, patient_id BIGINT NOT NULL, visit_id BIGINT, action VARCHAR(50), detail TEXT, operator_name VARCHAR(100), create_time DATETIME) ENGINE=InnoDB;
CREATE TABLE patient_ra_extra (patient_id BIGINT PRIMARY KEY, diagnosis_informed TINYINT NULL, consent_signed TINYINT NULL) ENGINE=InnoDB;
